package com.bank.cache;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LruCacheDemo {

    private static final Logger log = Logger.getLogger(LruCacheDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LruBalanceCache cache = new LruBalanceCache(2);

        cache.put("SAV2001", new BigDecimal("1000000"));  // Rajesh
        cache.put("CUR3001", new BigDecimal("250000"));   // Priya

        log.info(() -> "Get SAV2001: " + cache.get("SAV2001")); // touches Rajesh

        // Capacity 2, now adding a third → evict least recently used (CUR3001)
        cache.put("SAV2099", new BigDecimal("75000"));

        log.info(() -> "Get CUR3001: " + cache.get("CUR3001")); // null, evicted
        log.info(() -> "Get SAV2001: " + cache.get("SAV2001")); // still present
    }
}

