class LruBalanceCache {

    private static final Logger log = Logger.getLogger(LruBalanceCache.class.getName());

    // Doubly linked node: key+value+neighbours.
    private static final class Node {
        String key; BigDecimal value; Node prev, next;
        Node(String key, BigDecimal value) { this.key = key; this.value = value; }
    }

    private final int capacity;
    private final java.util.Map<String, Node> map = new java.util.HashMap<>();
    private final Node head = new Node(null, null);   // sentinel: most recent side
    private final Node tail = new Node(null, null);   // sentinel: least recent side

    LruBalanceCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    BigDecimal get(String key) {
        Node node = map.get(key);
        if (node == null) return null;
        moveToFront(node);                 // mark most recently used
        return node.value;
    }

    void put(String key, BigDecimal value) {
        Node existing = map.get(key);
        if (existing != null) {
            existing.value = value;
            moveToFront(existing);
            return;
        }
        Node node = new Node(key, value);
        map.put(key, node);
        addFront(node);
        if (map.size() > capacity) {
            Node lru = tail.prev;          // least recently used
            remove(lru);
            map.remove(lru.key);
            log.info(() -> "  evicted LRU key " + lru.key);
        }
    }

    private void addFront(Node n) {
        n.prev = head; n.next = head.next;
        head.next.prev = n; head.next = n;
    }

    private void remove(Node n) {
        n.prev.next = n.next; n.next.prev = n.prev;
    }

    private void moveToFront(Node n) {
        remove(n); addFront(n);
    }
}

